r","wb_run_state_transition","WorkbenchRunJobs","CREATE TRIGGER wb_run_state_transition\n        BEFORE UPDATE ON WorkbenchRunJobs WHEN\n        OLD.state IN (''complete'',''partial'',''failed'',''interrupted'') OR\n        NOT (NEW.state=OLD.state OR (OLD.state=''queued'' AND NEW.state IN (''running'',''interrupted''))\n             OR (OLD.state=''running'' AND NEW.state IN (''complete'',''partial'',''failed'',''interrupted'')))\n        BEGIN SELECT RAISE(ABORT,''invalid run transition''); END"],["trigger","wb_runcandidates_no_delete","WorkbenchRunCandidates","CREATE TRIGGER wb_runcandidates_no_delete BEFORE DELETE ON WorkbenchRunCandidates BEGIN SELECT RAISE(ABORT,''run ledger is permanent''); END"],["trigger","wb_runcandidates_no_update","WorkbenchRunCandidates","CREATE TRIGGER wb_runcandidates_no_update BEFORE UPDATE ON WorkbenchRunCandidates BEGIN SELECT RAISE(ABORT,''run ledger is permanent''); END"],["trigger","wb_runcandidatetasks_no_delete","WorkbenchRunCandidateTasks","CREATE TRIGGER wb_runcandidatetasks_no_delete BEFORE DELETE ON WorkbenchRunCandidateTasks BEGIN SELECT RAISE(ABORT,''run ledger is permanent''); END"],["trigger","wb_runcandidatetasks_no_update","WorkbenchRunCandidateTasks","CREATE TRIGGER wb_runcandidatetasks_no_update BEFORE UPDATE ON WorkbenchRunCandidateTasks BEGIN SELECT RAISE(ABORT,''run ledger is permanent''); END"],["trigger","wb_runjobs_no_delete","WorkbenchRunJobs","CREATE TRIGGER wb_runjobs_no_delete BEFORE DELETE ON WorkbenchRunJobs BEGIN SELECT RAISE(ABORT,''run ledger is permanent''); END"],["trigger","wb_runreceipts_no_delete","WorkbenchRunReceipts","CREATE TRIGGER wb_runreceipts_no_delete BEFORE DELETE ON WorkbenchRunReceipts BEGIN SELECT RAISE(ABORT,''run ledger is permanent''); END"],["trigger","wb_runreceipts_no_update","WorkbenchRunReceipts","CREATE TRIGGER wb_runreceipts_no_update BEFORE UPDATE ON WorkbenchRunReceipts BEGIN SELECT RAISE(ABORT,''run ledger is permanent''); END"]],"tables":{"BatchMaterials":[],"BatchOper